use bevy::prelude::*;
use serde_json::{Value,json};
use bevy_als::als::{params::AlsMovementParams,dynamics::{grounded_velocity_step_with_braking_friction,simulate_grounded_velocity_with_braking_friction}};
fn n(x:&Value)->f32{x.as_f64().unwrap()as f32}
fn mapped(x:&Value)->Vec3{Vec3::new(n(&x["x"]),n(&x["z"]),n(&x["y"]))}
fn raw(input:Vec2,yaw:f32)->Vec3{let a=bevy_als::als::motion::view_relative_move_axes(input,yaw);Vec3::new(a.x,0.,-a.y)}
fn source_sincos(value:f32)->(f32,f32){let q=(0.31830988618f32*0.5)*value;let q=if value>=0.{((q+0.5)as i64)as f32}else{((q-0.5)as i64)as f32};let mut y=value-6.28318530717f32*q;let sign;if y>1.57079632679f32{y=3.1415926535897932f32-y;sign=-1.;}else if y< -1.57079632679f32{y= -3.1415926535897932f32-y;sign=-1.;}else{sign=1.;}let y2=y*y;let sin=(((((-2.3889859e-08f32*y2+2.7525562e-06)*y2-0.00019840874)*y2+0.0083333310)*y2-0.16666667)*y2+1.)*y;let cos=((((-2.6051615e-07f32*y2+2.4760495e-05)*y2-0.0013888378)*y2+0.041666638)*y2-0.5)*y2+1.;(sin,sign*cos)}
fn main(){let doc:Value=serde_json::from_str(&std::fs::read_to_string("docs/audit/bf144/442b/matrix-inputs.json").unwrap()).unwrap();let observed:Value=serde_json::from_str(&std::fs::read_to_string("docs/audit/bf144/442/runtime-baseline/parameters.json").unwrap()).unwrap();let mut rows=Vec::new();for row in doc["geometry_query_probe"]["samples"].as_array().unwrap(){let input=&row["input"]["move_input"];let reproduced_r=(input["yaw_degrees"].as_f64().unwrap()as f32)*(3.1415926535897932f32/180.);assert_eq!(reproduced_r,n(&row["move_input"]["yaw_radians_float"]));let source=&row["move_input"];let sx=n(&input["axes"][0]);let sy=n(&input["axes"][1]);let shared=Vec2::new(sy,-sx);let r=n(&source["yaw_radians_float"]);let cx=n(&source["clamped_x"]);let cy=n(&source["clamped_y"]);let clamped=Vec2::new(cy,-cx);let sin=n(&source["forward"]["y"]);let cos=n(&source["forward"]["x"]);let pair=source_sincos(r);assert_eq!(pair,(sin,cos),"Source minimax must match native same-radian pair");let ox=input["axes"][0].as_f64().unwrap();let oy=input["axes"][1].as_f64().unwrap();let square=ox*ox+oy*oy;let factor=if square>1.{1./square.sqrt()}else{1.};let dx=ox*factor;let dy=oy*factor;assert_eq!((dx,dy),(source["clamped_x"].as_f64().unwrap(),source["clamped_y"].as_f64().unwrap()));let produced=bevy::math::DVec3::new(cos as f64*dy-sin as f64*dx,0.,sin as f64*dy+cos as f64*dx);assert_eq!(produced.x,source["world_input"]["x"].as_f64().unwrap());assert_eq!(produced.z,source["world_input"]["y"].as_f64().unwrap());let q=produced.x*produced.x+produced.z*produced.z;let source_cmc=if q>1.{produced*(1./q.sqrt())}else{produced};assert_eq!(source_cmc.x,source["cmc_input"]["x"].as_f64().unwrap());assert_eq!(source_cmc.z,source["cmc_input"]["y"].as_f64().unwrap());
let native_trig_f32=Vec3::new(cos*cy-sin*cx,0.,sin*cy+cos*cx);let std_raw=raw(clamped,-r);let native_raw=mapped(&source["world_input"]);let native_cmc=mapped(&source["cmc_input"]);let shared_current=bevy_als::als::motion::view_relative_move_direction(shared,-r)*shared.length().min(1.);let same_raw_normalized=native_raw.normalize_or_zero()*Vec2::new(cx,cy).length().min(1.);let same_raw_unnormalized=native_raw;let semantic_yaw=(-(input["yaw_degrees"].as_f64().unwrap().to_radians())-std::f64::consts::FRAC_PI_2)as f32;let semantic_input=Vec2::new(sx,sy);let semantic_current=bevy_als::als::motion::view_relative_move_direction(semantic_input,semantic_yaw)*semantic_input.length().min(1.);
let params=AlsMovementParams::default();let dynamics=params.grounded_dynamics(bevy_als::als::state::Stance::Standing,bevy_als::als::state::RotationMode::ViewDirection,0.);let plan=|d|grounded_velocity_step_with_braking_friction(Vec3::ZERO,d,3.75,dynamics,0.25,0.,params.cmc.braking_substep_time,1.0/30.);
let current_cached=shared_current.clamp_length_max(1.)*20.;let native_cached=native_cmc*20.;let norm_cached=same_raw_normalized.clamp_length_max(1.)*20.;
let actual_consumers=if let Some(name)=row["input"]["name"].as_str().and_then(|v|v.strip_prefix("observed-")){let i=name.parse::<usize>().unwrap();let old=&observed["rows"][i];assert_eq!(semantic_yaw,n(&old["consumed_yaw"]));let vector=|v:&Value|Vec3::new(n(&v[0]),n(&v[1]),n(&v[2]));assert_eq!(semantic_current,vector(&old["desired_motion"]));let d=&old["dynamics"];let actual_d=bevy_als::als::params::GroundedDynamics{acceleration:n(&d[0]),braking_deceleration:n(&d[1]),ground_friction:n(&d[2])};let run=|dir|simulate_grounded_velocity_with_braking_friction(vector(&old["relative_velocity_consumed"]),dir,n(&old["max_speed"]),actual_d,&params.cmc,n(&old["braking_friction_factor"]),n(&old["delta"])).0;let current=run(semantic_current);assert_eq!(current,vector(&old["planned_velocity"]));json!({"ordinal":i,"current":current.to_array(),"source_angular_input":run(native_cmc).to_array(),"reduced_angle_standard_math":run(shared_current).to_array()})}else{Value::Null};
rows.push(json!({"name":row["input"]["name"],"actual_consumers":actual_consumers,"source_minimax_pair":[pair.0,pair.1],"independent_full_source_cmc_double":[source_cmc.x,source_cmc.y,source_cmc.z],"source_producer_all_stages_native_exact":true,"same_raw_extra_norm_double_projected":(if q>0.{produced*(1./q.sqrt())}else{produced}).as_vec3().to_array(),"current_target_cached_acceleration":current_cached.to_array(),"same_native_input_cached_acceleration":native_cached.to_array(),"same_raw_extra_norm_cached_acceleration":norm_cached.to_array(),"current_public_plan":plan(shared_current).to_array(),"standard_trig_without_extra_norm_public_plan":plan(std_raw).to_array(),"native_input_public_plan":plan(native_cmc).to_array(),"same_raw_extra_norm_public_plan":plan(same_raw_normalized).to_array(),"no_extra_norm_public_plan":plan(same_raw_unnormalized).to_array(),"source":source,"source_input":input,"common_radian_runtime_yaw":-r,"shared_current":shared_current.to_array(),"shared_current_cmc":shared_current.clamp_length_max(1.).to_array(),"standard_trig_raw_with_source_clamp":std_raw.to_array(),"native_trig_raw_f32_with_source_clamp":native_trig_f32.to_array(),"native_raw_projected":native_raw.to_array(),"native_cmc_projected":native_cmc.to_array(),"same_raw_normalized":same_raw_normalized.to_array(),"same_raw_normalized_cmc":same_raw_normalized.clamp_length_max(1.).to_array(),"same_raw_without_extra_norm_cmc":same_raw_unnormalized.clamp_length_max(1.).to_array(),"physical_protocol_runtime_yaw":semantic_yaw,"physical_protocol_current":semantic_current.to_array(),"physical_protocol_current_cmc":semantic_current.clamp_length_max(1.).to_array()}));}
std::fs::write(std::env::args().nth(1).unwrap(),json!(rows).to_string()).unwrap();println!("Captured native and current direction stages for77 same-input physical-basis and shared-operator cases");}
